'use strict';
window.openBattleMenu=()=>{pausePlayerOverlay();const locked=typeof friendRoom!=='undefined'&&friendRoom?.mode==='online'&&['preparing','playing'].includes(friendRoom.status)&&!friendRoom.departed;document.getElementById('btn-battle-quit').hidden=!!locked;const special=battleMode==='special'&&!!specialChallenge;const trial=battleMode==='friend-cpu'||special||isPractice()&&['promotion-boss','promotion-mission','condition','cpu-skill'].includes(practiceRun.kind);document.getElementById('btn-trial-retry').hidden=!trial;document.getElementById('btn-trial-retry').textContent='同じ挑戦をリトライ';document.getElementById('btn-trial-retry').disabled=isPractice()&&practiceRun.kind==='cpu-skill'&&practiceRun.challenge.season!==KanjiCpuSkill.seasonId(cpuSkillNow());document.getElementById('btn-battle-quit').textContent=battleMode==='friend'?'部屋から退出':isPractice()&&practiceRun.kind==='cpu-skill'?'CPU腕試しに戻る':special?'この対局を終了':trial?'リタイアして試練に戻る':'この対局を終了';document.getElementById('modal-battle-menu').classList.remove('hidden');document.getElementById('battle-menu-note').textContent=battleMode==='friend'?'対人戦はメニューを開いても進行します。時間制限にご注意ください。対局中に「部屋から退出」を押すと敗北になります。':'対局を一時停止しました。「対局に戻る」で再開、「この対局を終了」で遊ぶ画面に戻ります。終了すると途中の盤面は失われます。';if(battleMode==='friend-cpu'){document.getElementById('btn-battle-quit').textContent='フレンド一覧に戻る';document.getElementById('battle-menu-note').textContent='フレンドの保存した編成とのCPU対戦を一時停止しました。同じ編成・レベル・配置でリトライできます。段位ポイント・対人RPは変動しません。';}if(locked)document.getElementById('battle-menu-note').textContent='オンライン対戦はマッチ成立後、対局終了まで退出できません。メニューを開いても対局は進みます。';if(isPractice()&&practiceRun.kind==='cpu-skill')document.getElementById('battle-menu-note').textContent='対局を一時停止しました。「同じ挑戦をリトライ」で開始時の編成・相手・配置のまま、準備画面を挟まずにやり直せます。自己ベストは保持します。「CPU腕試しに戻る」で課題一覧へ戻ります。';if(special)document.getElementById('battle-menu-note').textContent='対局を一時停止しました。同じ部隊・相手レベル・開始時の編成と配置でリトライできます。獲得済みの勲章と達成記録は保持します。';document.getElementById('btn-battle-resume').focus();};
window.closeBattleMenu=()=>{document.getElementById('modal-battle-menu').classList.add('hidden');resumePlayerEngine();document.getElementById('btn-battle-menu').focus();};
window.retryTrialFromMenu=()=>{if(isPractice()&&practiceRun.kind==='cpu-skill'){retryCpuSkillChallenge();return;}if(battleMode==='friend-cpu'){retryFriendCpuBattle();return;}if(battleMode==='special'&&specialChallenge){specialChallenge.finished=false;specialChallenge.won=false;document.getElementById('modal-battle-menu').classList.add('hidden');document.getElementById('modal-result').classList.add('hidden');resetBattle(false,true);return;}interruptPracticeChallenge(true);};
window.quitBattleFromMenu=async()=>{if(battleMode==='friend-cpu'){endFriendCpuBattle();return;}if(isPractice()&&['promotion-boss','promotion-mission','condition','cpu-skill'].includes(practiceRun.kind)){interruptPracticeChallenge(false);return;}if(battleMode==='friend'){await leaveFriendRoom();if(friendRoom)return;}else{setAutoBattle(false);setAutoContinue(false);clearTimeout(cpuTurnTimer);clearTimeout(playerTurnTimer);battleVersion++;isBattleEnded=true;endlessRun=null;specialChallenge=null;practiceRun=null;battleMode='classic';resetBattle();}document.getElementById('modal-battle-menu').classList.add('hidden');switchTab('play');};
document.addEventListener('keydown',e=>{const modal=document.getElementById('modal-battle-menu');if(modal.classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();closeBattleMenu();}if(e.key==='Tab'){const b=[...modal.querySelectorAll('button')].filter(b=>!b.hidden),first=b[0],last=b.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
